function blk(key, label, head, subs, o = {}) {
  const t0 = c2;
  if (label) LOG2.push({ t: t0, segs: [[label, P.dim]], size: 18, h: 30, fam: MONO });
  const ht = t0 + (label ? .2 : 0);
  const headItem = { t: ht, segs: head, size: 24, h: 38, weight: 700, cps: o.cps || 120 };
  if (o.typed) Object.assign(headItem, { typed: true, typeStart: ht + .3, cps: 30, promptLen: 2 });
  LOG2.push(headItem);
  let st = ht + (o.typed ? .3 + (itemText(headItem).length - 2) / 30 : .2);
  const subT = [];
  subs.forEach((sp, k) => {
    const spec = Array.isArray(sp) ? { s: sp } : sp;
    st += spec.d ?? (k === 0 ? .45 : .45); subT.push(st);
    LOG2.push({ t: st, segs: spec.s, size: 22, h: 34, indent: 30, cps: 100 });
  });
  LOG2.push({ t: (subT.length ? subT[subT.length - 1] : st) + .05, h: 12 });
  const last = subT.length ? subT[subT.length - 1] : st;
  const t1 = last + (o.hold ?? 2.6);
  headItem.hl = [ht, t1];
  capAdd(o.cap, t0, t1);
  B[key] = { t0, ht, subT, t1, last };
  c2 = t1;
}
